  function finishOther(st,meta,stem,choices,correct,explanation,seed,family){
    const r=rng(seed*1451+family.length*43);const tagged=choices.map((text,i)=>({text:String(text),ok:i===correct,rat:''}));const mixed=shuffle(r,tagged);const ci=mixed.findIndex(x=>x.ok);
    const item={...meta,subtest:st,questionType:'mcq',stem,choices:mixed.map(x=>x.text),correctIndex:ci,explanation,distractorRationale:mixed.map(x=>x.rat),difficulty:meta.difficulty||'hard',family,sourceClass:'ORIGINAL_REASONING',sourceBasis:'Official ETS Praxis 5001 content specification + user-provided study-plan scope; original reasoning item.',id:`${st}-${meta.topic}-${family}-${seed}`,fingerprint:`${st}|${meta.topic}|${family}|${stem.replace(/\s+/g,' ').trim().slice(0,180)}`};
    return validateItem(item).ok?item:null;
  }
